// ============================================================
// TutorBot · Escenario 1 · Alerta de disponibilidad critica
// Se ejecuta cada hora. Para cada tutor activo calcula, en la ventana
// proxima, cuantos bloques tiene habilitados y cuantos ya estan reservados.
// Si no le queda cupo (o le queda muy poco) avisa a coordinacion.
//
// IDEMPOTENCIA: una alerta por tutor y por dia. La marca no va en una columna
// nueva sino en LOG_EVENTOS: si ya hay un evento 'alerta_disponibilidad' de
// hoy para ese tutor, no se repite. Reejecutar cada hora no genera spam.
//
// Si no hay nada que alertar devuelve 0 items y el resto del workflow
// no se ejecuta.
// ============================================================
const cfg = $('Config').first().json;

const VENTANA   = Number(cfg.VENTANA_ALERTA_DIAS || 14);   // dias hacia adelante
const UMBRAL    = Number(cfg.UMBRAL_BLOQUES_LIBRES || 2);  // <= esto ya es critico
const DUR       = Number(cfg.DURACION_MIN || 60);
const OCUPAN    = ['ASIGNADA', 'CONFIRMADA'];
const DIAS      = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const aMin = h => { const m = /^(\d{1,2}):(\d{2})/.exec(String(h == null ? '' : h).trim()); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const tutores  = filas('Leer TUTORES').filter(t => String(t.id_tutor || '') !== '');
const dispo    = filas('Leer DISPONIBILIDAD').filter(d => String(d.id_tutor || '') !== '');
const tutorias = filas('Leer TUTORIAS').filter(t => String(t.id_tutoria || '') !== '');
const eventos  = filas('Leer LOG_EVENTOS');

// ---- Fechas de la ventana ----
const p = String(cfg.hoy).split('-').map(Number);
const baseUTC = Date.UTC(p[0], p[1] - 1, p[2]);
const fechas = [];
for (let i = 0; i < VENTANA; i++) {
  const d = new Date(baseUTC + i * 86400000);
  fechas.push({ iso: d.toISOString().slice(0, 10), dia: DIAS[d.getUTCDay()] });
}
const hasta = fechas[fechas.length - 1].iso;

// ---- Ya se aviso hoy de este tutor? ----
const avisadosHoy = new Set(
  eventos
    .filter(e => norm(e.evento) === 'alerta_disponibilidad' &&
                 String(e.timestamp || '').slice(0, 10) === String(cfg.hoy))
    .map(e => String(e.id_entidad || ''))
);

const salida = [];

for (const t of tutores) {
  if (norm(t.estado) !== 'activo') continue;
  const id = String(t.id_tutor);

  // Bloques habilitados por el tutor en la ventana
  const franjas = dispo.filter(d => String(d.id_tutor) === id && norm(d.estado) !== 'deshabilitada');
  let capacidad = 0;
  const bloques = [];   // {fecha, hora}
  for (const f of fechas) {
    for (const fr of franjas) {
      if (norm(fr.dia_semana) !== norm(f.dia)) continue;
      const ini = aMin(fr.hora_inicio), fin = aMin(fr.hora_fin);
      if (ini == null || fin == null || fin <= ini) continue;
      for (let m = ini; m + DUR <= fin; m += DUR) {
        capacidad++;
        bloques.push({ fecha: f.iso, min: m });
      }
    }
  }
  if (capacidad === 0) continue;   // sin franjas declaradas: no es "sin cupo", es otro problema

  // Bloques ya tomados dentro de la ventana
  const reservas = tutorias.filter(x =>
    String(x.id_tutor) === id &&
    OCUPAN.includes(String(x.estado || '').toUpperCase()) &&
    String(x.fecha) >= cfg.hoy && String(x.fecha) <= hasta
  );
  const tomados = new Set(reservas.map(x => String(x.fecha) + '|' + aMin(x.hora)));
  const libres = bloques.filter(b => !tomados.has(b.fecha + '|' + b.min)).length;

  if (libres > UMBRAL) continue;                 // todavia tiene aire
  if (avisadosHoy.has(id)) continue;             // ya se aviso hoy

  const nivel = libres === 0 ? 'SIN_CUPO' : 'CRITICO';
  const ocupacion = Math.round((capacidad - libres) / capacidad * 1000) / 10;

  // Que materias quedan expuestas si este tutor se saturo
  const materias = String(t.especialidad_materias || '').split(/[;,|]/).map(s => s.trim()).filter(Boolean);
  const otros = tutores.filter(o =>
    String(o.id_tutor) !== id && norm(o.estado) === 'activo' &&
    String(o.especialidad_materias || '').split(/[;,|]/).map(s => norm(s.trim())).some(m => materias.map(norm).includes(m))
  );
  const expuestas = materias.filter(m => !otros.some(o =>
    String(o.especialidad_materias || '').split(/[;,|]/).map(s => norm(s.trim())).includes(norm(m))
  ));

  const asunto = (nivel === 'SIN_CUPO' ? 'SIN CUPO' : 'Disponibilidad critica') +
                 ': ' + (t.nombre || id);

  const cuerpo = [
    nivel === 'SIN_CUPO'
      ? 'El tutor no tiene un solo bloque libre en los proximos ' + VENTANA + ' dias.'
      : 'Al tutor le quedan ' + libres + ' bloque(s) libre(s) en los proximos ' + VENTANA + ' dias.',
    '',
    'Tutor: ' + (t.nombre || id) + ' (' + id + ')',
    'Materias: ' + (materias.join(', ') || 'sin declarar'),
    'Periodo evaluado: ' + cfg.hoy + ' a ' + hasta,
    '',
    'Bloques habilitados: ' + capacidad,
    'Bloques reservados: ' + (capacidad - libres),
    'Bloques libres: ' + libres,
    'Ocupacion: ' + ocupacion + '%',
    '',
    expuestas.length
      ? 'ATENCION: ninguna otra persona activa dicta ' + expuestas.join(', ') +
        '. Si este tutor se llena, esa demanda queda sin cubrir.'
      : 'Las materias de este tutor tienen cobertura de otros tutores activos.',
    '',
    'Acciones posibles: ampliar sus franjas en la hoja DISPONIBILIDAD,',
    'habilitar otro tutor para esas materias, o revisar si hay reservas que se pueden reprogramar.',
    '',
    'Datos tomados de TutorBot_DB. Alerta generada el ' + cfg.ahora_iso + '.'
  ].join('\n');

  salida.push({
    json: {
      id_tutor: id,
      nombre_tutor: String(t.nombre || id),
      nivel: nivel,
      capacidad: capacidad,
      reservados: capacidad - libres,
      libres: libres,
      ocupacion_pct: ocupacion,
      materias_expuestas: expuestas,
      asunto: 'TutorBot · ' + asunto,
      mensaje: esc(cuerpo),
      log: {
        id_evento: 'EV-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 14) + '-' + id,
        timestamp: cfg.ahora_iso,
        telegram_user: 'sistema',
        evento: 'alerta_disponibilidad',
        entidad: 'tutor',
        id_entidad: id,
        detalle: nivel + ' | libres ' + libres + '/' + capacidad + ' | ocupacion ' + ocupacion + '%'
      }
    }
  });
}

// Los mas saturados primero
salida.sort((a, b) => a.json.libres - b.json.libres);
return salida;
